struct ch_adapter {
    mqd_t out;                             /* application -> channel */
    void (*on_msg)(struct order *o, void *ud);
    void *ud;
};

int ca_publish(struct ch_adapter *a, const struct order *o) {
    char buf[256];
    size_t n = order_encode(o, buf, sizeof buf);
    return mq_send(a->out, buf, n, 0);     /* 0 on success, -1 + errno */
}
